const r="\ufeff// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n// 额外注入：ElMessage, ElMessageBox\r\n\r\nlet selectedUser = null;\r\n\r\n// 页面初始化\r\nconsole.log('🔗 级联演示页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('handleUserRowChange', function(currentRow) {\r\n  selectedUser = currentRow;\r\n  if (currentRow) {\r\n    console.log('✅ 选中用户:', currentRow);\r\n  }\r\n});\r\n\r\nregisterFunction('handleAddUser', async function() {\r\n  try {\r\n    const { value: name } = await ElMessageBox.prompt('请输入用户名', '添加用户', {\r\n      confirmButtonText: '确定',\r\n      cancelButtonText: '取消',\r\n      inputPattern: /.+/,\r\n      inputErrorMessage: '用户名不能为空'\r\n    });\r\n\r\n    const { value: email } = await ElMessageBox.prompt('请输入邮箱', '添加用户', {\r\n      confirmButtonText: '确定',\r\n      cancelButtonText: '取消',\r\n      inputPattern: /^.+@.+\\..+$/,\r\n      inputErrorMessage: '请输入有效的邮箱地址'\r\n    });\r\n\r\n    const dataSet = $dataSet();\r\n    const userTable = dataSet.getTable('Users');\r\n\r\n    const maxId = Math.max(...userTable.rows.map(r => r.id), 0);\r\n    const newUser = { id: maxId + 1, name, email };\r\n\r\n    // 低代码：直接操作，内核通知订阅者，UI自动更新\r\n    userTable.rows.push(newUser);\r\n    dataSet.notifySubscribers('Users'); // 手动触发通知\r\n\r\n    ElMessage.success(`✅ 用户添加成功: ${name}`);\r\n  } catch (error) {\r\n    if (error !== 'cancel') {\r\n      console.error('添加用户失败:', error);\r\n      ElMessage.error('添加用户失败');\r\n    }\r\n  }\r\n});\r\n\r\nregisterFunction('handleUpdateUserIdBatch', async function() {\r\n  try {\r\n    const { value: offset } = await ElMessageBox.prompt(\r\n      '输入要增加的ID偏移量（例如：100），订单的userId会自动级联更新',\r\n      '批量修改用户ID',\r\n      {\r\n        confirmButtonText: '确定',\r\n        cancelButtonText: '取消',\r\n        inputPattern: /^\\d+$/,\r\n        inputErrorMessage: '请输入正整数'\r\n      }\r\n    );\r\n\r\n    const dataSet = $dataSet();\r\n    const userTable = dataSet.getTable('Users');\r\n    const offsetNum = parseInt(offset);\r\n\r\n    // 低代码：遍历更新，内核自动级联\r\n    userTable.rows.forEach(user => {\r\n      const oldValues = { ...user };\r\n      user.id += offsetNum;\r\n      dataSet.cascadeUpdate('Users', user, oldValues);\r\n    });\r\n\r\n    ElMessage.success(`✅ 已批量更新 ${userTable.rows.length} 个用户ID，订单已自动级联更新`);\r\n  } catch (error) {\r\n    if (error !== 'cancel') {\r\n      console.error('批量更新失败:', error);\r\n      ElMessage.error('批量更新失败');\r\n    }\r\n  }\r\n});\r\n\r\nregisterFunction('handleDeleteSelectedUser', async function() {\r\n  if (!selectedUser) {\r\n    ElMessage.warning('请先点击表格中的一行选择用户');\r\n    return;\r\n  }\r\n\r\n  try {\r\n    const dataSet = $dataSet();\r\n    const Users = dataSet.getTable('Users');\r\n    const Orders = dataSet.getTable('Orders');\r\n    const OrderItems = dataSet.getTable('OrderItems');\r\n\r\n    // 统计关联数据（仅用于提示）\r\n    const relatedOrders = Orders.rows.filter(o => o.userId === selectedUser.id);\r\n    const relatedOrderIds = relatedOrders.map(o => o.id);\r\n    const relatedOrderItems = OrderItems.rows.filter(item =>\r\n      relatedOrderIds.includes(item.orderId)\r\n    );\r\n\r\n    await ElMessageBox.confirm(\r\n      `确定要删除用户 \"${selectedUser.name}\" 吗？\\n\\n⚠️ 这将会级联删除：\\n` +\r\n      `• ${relatedOrders.length} 个订单\\n` +\r\n      `• ${relatedOrderItems.length} 个订单明细`,\r\n      '危险操作',\r\n      {\r\n        confirmButtonText: '确定删除',\r\n        cancelButtonText: '取消',\r\n        type: 'warning'\r\n      }\r\n    );\r\n\r\n    const index = Users.rows.findIndex(u => u.id === selectedUser.id);\r\n\r\n    if (index !== -1) {\r\n      // 1. 先删除父行（修改数据）\r\n      Users.rows.splice(index, 1);\r\n\r\n      // 2. 再调用级联删除（内核处理子表删除并通知订阅者）\r\n      // 注意：必须先修改数据再通知，否则 UI 绑定时数据还是旧的\r\n      dataSet.cascadeDelete('Users', selectedUser);\r\n\r\n      ElMessage.success(\r\n        `✅ 用户删除成功！\\n级联删除了 ${relatedOrders.length} 个订单和 ${relatedOrderItems.length} 个明细`\r\n      );\r\n      selectedUser = null;\r\n    }\r\n  } catch (error) {\r\n    if (error !== 'cancel') {\r\n      console.error('删除失败:', error);\r\n      ElMessage.error('删除失败');\r\n    }\r\n  }\r\n});\r\n\r\n\r\n";export{r as default};
